import {escapeHtml as esc} from './components.js';
const number=v=>v===null||v===undefined?'미확인':Number(v).toLocaleString('ko-KR',{maximumFractionDigits:2});
const scope=v=>({CONSOLIDATED:'연결',SEPARATE:'별도',SEGMENT:'사업부',SUBSIDIARY:'자회사'}[v]||'연결·별도 미확인');
const basis=v=>({ANNUAL:'연간',YTD:'누적',HALF_YEAR:'반기 누적',SINGLE_QUARTER:'단일 분기'}[v]||'기간 기준 미확인');
const safe=v=>{try{const u=new URL(v);return u.protocol==='https:'&&!u.username&&!u.password?u.href:null;}catch{return null;}};
function factLine(f,label){
 if(!f)return '';
 const warnings=f.warnings.filter(w=>!w.includes('연결·별도')),url=safe(f.source?.url),group=f.match==='product_group'?'제품 묶음':f.match==='company_segment_context'?'사업부 전체 · 해당 제품 단독 아님':'';
 return `<div class="nc-financial-fact"><p><strong>${esc(label)}</strong> ${esc(f.label)}${group?` <span>${esc(group)}</span>`:''} · ${f.rawValue!==null?`${esc(number(f.rawValue))} ${esc(f.unit)} (${esc(f.currency||'통화 미확인')})`:'금액 미확인'}${f.percent!==null?` · <b>${esc(number(f.percent))}%</b>`:' · 비중 미확인'}</p><p class="nc-financial-basis">${esc(f.period.start)}~${esc(f.period.end)} · ${esc(basis(f.period.type))} · ${esc(scope(f.scope))} · ${f.shareOrigin==='CALCULATED'?'같은 표의 금액÷합계':'공시값'}${f.geography?` · ${esc({CUSTOMER_LOCATION:'고객 소재지',SHIP_TO_LOCATION:'배송지',BILLING_LOCATION:'청구지',OPERATING_LOCATION:'사업장 소재지'}[f.geographyBasis]||'지역 산정 기준 미확인')}`:''}${url?` · <a href="${esc(url)}" target="_blank" rel="noopener noreferrer">매출 근거 ↗</a> · 공시 ${esc(f.source.publishedAt?.slice(0,10)||'일자 미확인')}`:''}</p>${f.denominatorValue!==null?`<p class="nc-financial-basis">분모 ${esc(number(f.denominatorValue))} ${esc(f.unit)} · ${esc(f.denominatorLabel||'공시 매출표 합계')}${warnings.some(w=>w.includes('범위 변경'))?' · 비교 기준 확인 필요':''}</p>`:''}</div>`;
}
export function financialMarkup(f,impact){
 if(!f&&!impact)return '';
 const missingLabel={FETCH_FAILED:'수집 실패 · 미공개로 판단하지 않음',STALE:'이전 자료 · 갱신 확인 필요',NOT_DISCLOSED:'공시에서 미공개 확인',NOT_COLLECTED:'아직 수집되지 않음'}[f?.states?.PRODUCT]||'미확인';
 const unit=impact?.currency?`${impact.currency} · ${number(impact.scale)} 기본 통화 단위`:'금액 미산출';
 return `<div class="nc-financial"><p class="nc-financial-title">매출 근거와 실적 경로</p>${f?`${factLine(f.business,'사업 매출')}${!f.business?`<p>제품 매출 근거 ${esc(missingLabel)}</p>`:''}${factLine(f.region,'지역 매출')}${!f.region?'<p>미국 매출 미확인 · 북미·수출 비중으로 대체하지 않습니다.</p>':''}${factLine(f.exports,'수출')}${f.business?.match!=='exact_product'?'<p class="nc-financial-basis">해당 제품 단독 비중은 미확인입니다. 묶음 비중을 기업 순위 조건에 사용하지 않습니다.</p>':''}<p class="nc-financial-basis">${esc(f.notice)}</p>`:''}${impact?`<div class="nc-impact"><p><strong>${impact.horizon?`${impact.horizon.start}~${impact.horizon.end}년 실적 경로`:impact.paths.length?`${impact.paths.map(p=>p.year).join('·')}년 사업 일정`:'실적 반영 연도 미확인'}</strong></p>${impact.paths.map(p=>`<p>${p.year}년 · ${esc(p.explanation)}</p>`).join('')}<ul class="nc-scenarios">${impact.scenarios.map(s=>{const calculated=s.rows.filter(r=>r.revenue!==null);return `<li><b>${esc(s.label)}</b> ${esc(s.description)}${calculated.length?calculated.map(r=>`<p>${r.year}년 사용자 가정 · 매출 ${esc(number(r.revenue))} / 증분 ${esc(number(r.incrementalRevenue))} (${esc(unit)})</p>`).join(''):' · 금액 미확인'}</li>`;}).join('')}</ul>${impact.status==='USER_SCENARIO'?`<p class="nc-financial-basis">입력한 가정으로 계산했습니다. 공시·회사 전망이 아닙니다. 증분 = 뉴스 반영 매출 − 추가 변화 없는 기준 매출.</p>${impact.scenarios.flatMap(s=>s.rows.filter(r=>r.inputs).map(r=>`<p class="nc-financial-basis">${s.label} ${r.year}년 민감도: ${r.sensitivity.map(x=>`${({contractRecognized:'당해 인식액',newOrders:'별도 신규 주문',recurringService:'반복 서비스',utilization:'가동률',supplierShare:'공급사 점유율',unitPrice:'단가',supplierCapacity:'공급능력'})[x.input]} ${x.unit} 증가 → 매출 ${number(x.revenueDelta)}`).map(esc).join(' · ')}${r.capBinding?' · 공급능력 상한 적용':''}${r.missing.length?' · 미확인 입력: '+r.missing.map(esc).join(', '):''}</p>`)).join('')}`:'<p class="nc-financial-basis">민감 변수: 공급사 채택·주문량·단가·매출 인식 시점. 입력값이 없어 수치 민감도는 계산하지 않았습니다.</p>'}<p class="nc-financial-basis">${esc(impact.caution)}</p></div>`:''}</div>`;
}
export function scenarioEditor(candidates){
 return `<form class="nc-scenario-form"><h4>내 가정으로 매출 계산</h4><p>원문 확인값과 별개로 저장합니다. 기존 매출을 중복 입력하거나 투자액·계약 총액을 당해 매출로 입력하지 마세요.</p><label>기업<select name="assetId">${candidates.map(c=>`<option value="${esc(c.asset.id)}">${esc(c.asset.name)}</option>`).join('')}</select></label><label>매출 구조<select name="model"><option value="equipment">장비·계약·서비스</option><option value="materials">소재·소모품</option></select></label><label>시나리오<select name="kind"><option value="base">기준</option><option value="conservative">보수</option><option value="expansion">확대</option><option value="delay">지연</option><option value="cancellation">취소</option></select></label><label>연도<input required type="number" name="year" min="2000" max="2100" placeholder="매출 인식 연도"></label><label>통화<select name="currency"><option>KRW</option><option>USD</option><option>EUR</option><option>JPY</option></select></label><label>단위<select name="scale"><option value="1000000">백만</option><option value="1">기본 단위</option><option value="1000">천</option><option value="100000000">억</option></select></label><div class="nc-scenario-equipment">${[['contractRecognized','해당 연도 계약 매출 인식액'],['newOrders','위 계약과 별개의 신규 주문 매출'],['recurringService','중복 없는 유지보수·서비스 매출']].map(([key,label])=>`<label>${label}<input type="number" name="${key}" min="0" max="1000000000000000" step="any" placeholder="미확인 · 0과 다름"></label>`).join('')}</div><div class="nc-scenario-materials" hidden><label>공정량 기준<select name="throughputBasis"><option value="INPUT">공정 투입량</option><option value="GOOD_OUTPUT">양품 생산량</option></select></label><label>공정 단위<select name="processUnit"><option value="panel">패널</option><option value="m2">㎡</option><option value="hole">홀</option><option value="coated_m2">도금면적 ㎡</option><option value="unit">개</option><option value="tonne">톤</option></select></label><label>소재 단위<select name="materialUnit"><option value="kg">kg</option><option value="litre">리터</option><option value="unit">개</option><option value="tonne">톤</option></select></label>${[['nominalThroughput','연간 명목 공정량'],['utilization','고객 가동률 (0~1)'],['customerYield','고객 수율 (0~1) · 양품→투입 환산에만 사용'],['consumptionPerUnit','공정 단위당 소재 사용량'],['supplierShare','공급사 점유율 (0~1)'],['unitPrice','소재 단위당 판매가 · 위 통화·단위'],['supplierCapacity','공급사 연간 생산능력 · 소재 단위'],['supplierYield','공급사 수율 (0~1)'],['inventoryReduction','재고 조정으로 감소하는 주문량 · 소재 단위']].map(([key,label])=>`<label>${label}<input type="number" name="${key}" min="0" max="${['utilization','customerYield','supplierShare','supplierYield'].includes(key)?1:1000000000000000}" step="any" placeholder="미확인"></label>`).join('')}<label>고객 승인 가정<select name="qualified"><option value="">미확인</option><option value="yes">승인</option><option value="no">미승인</option></select></label></div><label>뉴스 추가 변화가 없는 기준 매출<input type="number" name="baselineRevenue" min="0" max="1000000000000000" step="any" placeholder="미확인 · 0과 다름"></label><label><input required type="checkbox" name="exclusive">같은 매출을 중복 입력하지 않았고, 기준값에 이번 추가 효과를 포함하지 않았습니다.</label><button>가정 저장·계산</button><small>한 연도씩 추가합니다. 다른 시나리오·연도는 유지됩니다. 추가 AI 호출 없음.</small></form>`;
}
